INSERT INTO configuracion (clave, valor, descripcion) VALUES ('SERVICES_JSON', '[{"id":"mecanica","title":"Mecánica General & Mantenimiento","desc":"Mantenimiento preventivo y correctivo: cambio de aceite sintético, correa o cadena de distribución, empacaduras, bombas de agua y afinación de motor para Jeep, Toyota y más.","img":"https://mulxylpctqkfbfqeuvno.supabase.co/storage/v1/object/public/mastertech-media/servicios/1790972432178_imagen_representativa_jpg.webp"},{"id":"diagnostico","title":"Diagnóstico Electrónico & Escáner","desc":"Diagnóstico computarizado con escáner multimarca de nivel OEM. Lectura de códigos DTC, monitoreo de sensores en tiempo real y test de actuadores para detectar cualquier falla.","img":"https://mulxylpctqkfbfqeuvno.supabase.co/storage/v1/object/public/mastertech-media/servicios/1790972615347_imagen_representativa_jpg.webp"},{"id":"electricidad","title":"Electricidad & Electrónica Automotriz","desc":"Diagnóstico y reparación del sistema eléctrico: instalaciones, alternadores, baterías, fusibles, módulos electrónicos y electricidad general del vehículo.","img":"https://mulxylpctqkfbfqeuvno.supabase.co/storage/v1/object/public/mastertech-media/servicios/1790972511477_imagen_representativa_jpg.webp"},{"id":"frenos","title":"Frenos, Dirección & Suspensión","desc":"Cambio de pastillas cerámicas, rectificación de discos y tambores, amortiguadores, terminales de dirección, bujes y balanceo. Máxima seguridad en cada frenada.","img":"https://mulxylpctqkfbfqeuvno.supabase.co/storage/v1/object/public/mastertech-media/servicios/1791301440051_imagen_representativa_jpg.webp"},{"id":"inyectores","title":"Limpieza de Inyectores por Ultrasonido","desc":"Prueba en banco computarizado de inyección, limpieza ultrasónica de inyectores, medición de caudal y sustitución de microfiltros y sellos O-ring.","img":"https://mulxylpctqkfbfqeuvno.supabase.co/storage/v1/object/public/mastertech-media/servicios/1791301030573_imagen_representativa_jpg.webp"},{"id":"climatizacion","title":"Climatización & Aire Acondicionado","desc":"Carga de gas refrigerante R134a, lubricación del compresor con aceite PAG sintético, detección de fugas con trazador UV y mantenimiento integral del sistema A/C.","img":"/assets/servicio-climatizacion.webp"},{"id":"ecu","title":"Reprogramación ECU Stage 1 & 2","desc":"Calibración de software de motor para optimización de potencia y torque. Desactivación electrónica de EGR/DPF y remapeo de mapas de inyección para mayor rendimiento.","img":"https://mulxylpctqkfbfqeuvno.supabase.co/storage/v1/object/public/mastertech-media/servicios/1790972495966_imagen_representativa_jpg.webp"}]', 'Configuracion sincronizada desde Supabase');
