INSERT INTO configuracion (clave, valor, descripcion) VALUES ('INSTALACIONES_JSON', '[{"id":1790972654966,"badge":"Puesto #2","title":"Mecánica General & Mantenimiento","desc":"Mantenimiento preventivo y correctivo: cambio de aceite sintético, correa o cadena de distribución, empacaduras, bombas de agua y afinación de motor para Jeep, Toyota y más.","img":"https://mulxylpctqkfbfqeuvno.supabase.co/storage/v1/object/public/mastertech-media/servicios/1790972432178_imagen_representativa_jpg.webp","feature":"Garantía de calidad MasterTech","servicioId":"mecanica","servicioNombre":"Mecánica General & Mantenimiento"},{"id":1790972658220,"badge":"Puesto #2","title":"Diagnóstico Electrónico & Escáner","desc":"Diagnóstico computarizado con escáner multimarca de nivel OEM. Lectura de códigos DTC, monitoreo de sensores en tiempo real y test de actuadores para detectar cualquier falla.","img":"https://mulxylpctqkfbfqeuvno.supabase.co/storage/v1/object/public/mastertech-media/servicios/1790972615347_imagen_representativa_jpg.webp","feature":"Garantía de calidad MasterTech","servicioId":"diagnostico","servicioNombre":"Diagnóstico Electrónico & Escáner"},{"id":1790972659544,"badge":"Puesto #3","title":"Electricidad & Electrónica Automotriz","desc":"Diagnóstico y reparación del sistema eléctrico: instalaciones, alternadores, baterías, fusibles, módulos electrónicos y electricidad general del vehículo.","img":"https://mulxylpctqkfbfqeuvno.supabase.co/storage/v1/object/public/mastertech-media/servicios/1790972511477_imagen_representativa_jpg.webp","feature":"Garantía de calidad MasterTech","servicioId":"electricidad","servicioNombre":"Electricidad & Electrónica Automotriz"},{"id":1790972661288,"badge":"Reprogramación ECU Stage","title":"Reprogramación ECU Stage 1 & 2","desc":"Calibración de software de motor para optimización de potencia y torque. Desactivación electrónica de EGR/DPF y remapeo de mapas de inyección para mayor rendimiento.","img":"https://mulxylpctqkfbfqeuvno.supabase.co/storage/v1/object/public/mastertech-media/servicios/1790972495966_imagen_representativa_jpg.webp","feature":"Garantía de calidad MasterTech","servicioId":"ecu","servicioNombre":"Reprogramación ECU Stage 1 & 2"}]', 'Configuracion sincronizada desde Supabase');
