INSERT INTO configuracion (clave, valor, descripcion) VALUES ('JORNADAS_JSON', '[{"id":"jornada_1790972869724","badge":"Jornada Especial","title":"REPROGRAMACIÓN OPTIMIZACiÓN Y RENDIMIENTO DE MOTOR","subtitle":"Optimiza el rendimiento de tu motor ante las exigencias del combustible en Venezuela. Este servicio previene el pistoneo, mejora la respuesta de aceleración y protege componentes críticos. Incluye descarbonización especializada, banqueo de inyectores, pruebas en banco y carretera, resguardo audiovisual y garantía de 2 meses.","regularPrice":"Desde $950 USD","promoPrice":"Desde $698 USD","discountBadge":"3 CUPOS / MIÉRCOLES","duration":"Miércoles VIP","benefits":["Descarbonización especializada de motor","Banqueo y calibración de inyectores","Pruebas dinámicas en banco y carretera","Resguardo y reporte audiovisual completo del proceso"],"garantia":"2 Meses","specs":[{"label":"Descarbonización","val":"Entonación"},{"label":"Inyectores","val":"Banqueo"},{"label":"Pruebas","val":"Banco y Carretera"},{"label":"Garantía","val":"2 Meses"}],"compatibleModels":"4Runner (2010–2025) • Tacoma (2015–2026) • Highlander (2020–2026) • Corolla (2019–2026) • RAV4 (2019–2026) • Camry (2018–2026) • Levin (2020–2026) • Motores 4cil y 6cil (V35A, 2GR-SKF, M20A, 24AF)","img":"https://mulxylpctqkfbfqeuvno.supabase.co/storage/v1/object/public/mastertech-media/contenido/1790972921102_imagen_promocional_jpg.webp","jornadaDay":"3","dateLabel":"Fecha (Sólo Miércoles)","jornadaSlots":["08:30 AM","10:30 AM","02:00 PM"],"images":["https://mulxylpctqkfbfqeuvno.supabase.co/storage/v1/object/public/mastertech-media/jornadas/1791166418321_media_jpg.webp","https://mulxylpctqkfbfqeuvno.supabase.co/storage/v1/object/public/mastertech-media/jornadas/1791166453112_media_jpg.webp","https://mulxylpctqkfbfqeuvno.supabase.co/storage/v1/object/public/mastertech-media/jornadas/1791209679012_media_jpg.webp"],"packages":[{"id":"pkg_m20_1791391108317","name":"Motor 2.0L / 2.5L (M20A-FKS / A25A-FKS) no hibrido","subtitle":"Toyota TNGA 2.0 y 2.5L ","regularPrice":"$1,079 USD","promoPrice":"$698 USD","discountBadge":"AHORRAS $381 USD"},{"id":"pkg_t24a_1791391108317","name":"Motor Turbo 2.4L (T24A-FTS no híbrido)","subtitle":"Toyota TNGA motorización T24A-FTS","regularPrice":"$1,944 USD","promoPrice":"$1,299 USD","discountBadge":"AHORRAS $645 USD"},{"id":"pkg_v35a_1791391108317","name":"Motor Twin-Turbo 3.5L (V35A-FTS no híbrido)","subtitle":"Toyota TNGA motorización V35A-FTS","regularPrice":"$2,200 USD","promoPrice":"$1,499 USD","discountBadge":"AHORRAS $701 USD"}]}]', 'Configuracion sincronizada desde Supabase');
INSERT INTO servicios_taller (codigo, titulo, categoria, descripcion, duracion_estimada, precio_estimado_usd, imagen) VALUES ('mecanica', 'Mecánica General & Mantenimiento', 'Mecanica & Especialidad', 'Mantenimiento preventivo y correctivo: cambio de aceite sintético, correa o cadena de distribución, empacaduras, bombas de agua y afinación de motor para Jeep, Toyota y más.', '1 a 3 horas', 35, 'https://mulxylpctqkfbfqeuvno.supabase.co/storage/v1/object/public/mastertech-media/servicios/1790972432178_imagen_representativa_jpg.webp');
INSERT INTO servicios_taller (codigo, titulo, categoria, descripcion, duracion_estimada, precio_estimado_usd, imagen) VALUES ('diagnostico', 'Diagnóstico Electrónico & Escáner', 'Mecanica & Especialidad', 'Diagnóstico computarizado con escáner multimarca de nivel OEM. Lectura de códigos DTC, monitoreo de sensores en tiempo real y test de actuadores para detectar cualquier falla.', '1 a 3 horas', 35, 'https://mulxylpctqkfbfqeuvno.supabase.co/storage/v1/object/public/mastertech-media/servicios/1790972615347_imagen_representativa_jpg.webp');
INSERT INTO servicios_taller (codigo, titulo, categoria, descripcion, duracion_estimada, precio_estimado_usd, imagen) VALUES ('electricidad', 'Electricidad & Electrónica Automotriz', 'Mecanica & Especialidad', 'Diagnóstico y reparación del sistema eléctrico: instalaciones, alternadores, baterías, fusibles, módulos electrónicos y electricidad general del vehículo.', '1 a 3 horas', 35, 'https://mulxylpctqkfbfqeuvno.supabase.co/storage/v1/object/public/mastertech-media/servicios/1790972511477_imagen_representativa_jpg.webp');
INSERT INTO servicios_taller (codigo, titulo, categoria, descripcion, duracion_estimada, precio_estimado_usd, imagen) VALUES ('frenos', 'Frenos, Dirección & Suspensión', 'Mecanica & Especialidad', 'Cambio de pastillas cerámicas, rectificación de discos y tambores, amortiguadores, terminales de dirección, bujes y balanceo. Máxima seguridad en cada frenada.', '1 a 3 horas', 35, 'https://mulxylpctqkfbfqeuvno.supabase.co/storage/v1/object/public/mastertech-media/servicios/1791301440051_imagen_representativa_jpg.webp');
INSERT INTO servicios_taller (codigo, titulo, categoria, descripcion, duracion_estimada, precio_estimado_usd, imagen) VALUES ('inyectores', 'Limpieza de Inyectores por Ultrasonido', 'Mecanica & Especialidad', 'Prueba en banco computarizado de inyección, limpieza ultrasónica de inyectores, medición de caudal y sustitución de microfiltros y sellos O-ring.', '1 a 3 horas', 35, 'https://mulxylpctqkfbfqeuvno.supabase.co/storage/v1/object/public/mastertech-media/servicios/1791301030573_imagen_representativa_jpg.webp');
INSERT INTO servicios_taller (codigo, titulo, categoria, descripcion, duracion_estimada, precio_estimado_usd, imagen) VALUES ('climatizacion', 'Climatización & Aire Acondicionado', 'Mecanica & Especialidad', 'Carga de gas refrigerante R134a, lubricación del compresor con aceite PAG sintético, detección de fugas con trazador UV y mantenimiento integral del sistema A/C.', '1 a 3 horas', 35, '/assets/servicio-climatizacion.webp');
INSERT INTO servicios_taller (codigo, titulo, categoria, descripcion, duracion_estimada, precio_estimado_usd, imagen) VALUES ('ecu', 'Reprogramación ECU Stage 1 & 2', 'Mecanica & Especialidad', 'Calibración de software de motor para optimización de potencia y torque. Desactivación electrónica de EGR/DPF y remapeo de mapas de inyección para mayor rendimiento.', '1 a 3 horas', 35, 'https://mulxylpctqkfbfqeuvno.supabase.co/storage/v1/object/public/mastertech-media/servicios/1790972495966_imagen_representativa_jpg.webp');
